package in.sevasetu.amc.security;
import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;
import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;
@Service public class TokenService{
 private final byte[] secret;private final long hours;private final ObjectMapper json;
 public TokenService(@Value("${app.jwt-secret}")String secret,@Value("${app.jwt-hours}")long hours,ObjectMapper json){this.secret=secret.getBytes(StandardCharsets.UTF_8);this.hours=hours;this.json=json;}
 public String issue(CurrentUser u){try{var header=b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}".getBytes());var body=new LinkedHashMap<String,Object>();body.put("sub",u.userId().toString());body.put("tenant",u.tenantId()==null?null:u.tenantId().toString());body.put("username",u.username());body.put("name",u.displayName());body.put("role",u.role());body.put("exp",Instant.now().plusSeconds(hours*3600).getEpochSecond());var payload=b64(json.writeValueAsBytes(body));var unsigned=header+"."+payload;return unsigned+"."+b64(sign(unsigned));}catch(Exception e){throw new IllegalStateException("Could not issue token",e);}}
 public CurrentUser verify(String token){try{var p=token.split("\\.");if(p.length!=3||!MessageDigestSafe.equals(b64(sign(p[0]+"."+p[1])),p[2]))throw new IllegalArgumentException();var m=json.readValue(Base64.getUrlDecoder().decode(p[1]),Map.class);if(((Number)m.get("exp")).longValue()<Instant.now().getEpochSecond())throw new IllegalArgumentException();return new CurrentUser(UUID.fromString((String)m.get("sub")),m.get("tenant")==null?null:UUID.fromString((String)m.get("tenant")),(String)m.get("username"),(String)m.get("name"),(String)m.get("role"));}catch(Exception e){throw new IllegalArgumentException("Invalid or expired token");}}
 private byte[] sign(String v)throws Exception{var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret,"HmacSHA256"));return mac.doFinal(v.getBytes(StandardCharsets.UTF_8));}private String b64(byte[] v){return Base64.getUrlEncoder().withoutPadding().encodeToString(v);}
 private static class MessageDigestSafe{static boolean equals(String a,String b){return java.security.MessageDigest.isEqual(a.getBytes(StandardCharsets.UTF_8),b.getBytes(StandardCharsets.UTF_8));}}
}
